## What Problem This Solves

Fixes an issue where Google Meet realtime audio bridges could accept malformed base64 audio chunks from direct `googlemeet.chrome` calls or paired-node `pullAudio` responses.

## Why This Change Was Made

The Google Meet audio bridge now uses one owner-local base64 validation helper before policy forwarding, node-host playback, realtime voice input, and default agent transcription input. Valid audio chunks still flow through unchanged.

## User Impact

Malformed bridge audio is rejected or treated as a transient input failure instead of being decoded into arbitrary bytes and sent to playback, realtime voice, or agent transcription providers.

## Evidence

- `node scripts/run-vitest.mjs extensions/google-meet/src/node-invoke-policy.test.ts extensions/google-meet/node-host.test.ts extensions/google-meet/index.test.ts`: 160 tests passed.
- `node --import tsx --input-type=module -`: imported the real policy, realtime bridge, and default agent bridge modules, proving invalid direct `pushAudio` does not dispatch and invalid pulled audio does not reach either `provider.sendAudio` or `transcriptionSession.sendAudio` while valid control chunks still do.
- Real node-host command-pair run of the production `handleGoogleMeetNodeHostCommand` entrypoint (`start` then `pushAudio`); the only seam is the OS child process (the paired Chrome/bridge node), whose stdin is the downstream sink after the decode. A valid PCM chunk decodes and is written to the paired-node stdin intact, while malformed and base64url payloads are rejected before any bytes reach it:

```text
=== GOOGLE MEET NODE HOST (real handleGoogleMeetNodeHostCommand pushAudio) ===
[session] started bridgeId ok=true
[valid PCM 1920B] pushAudio ok=true  bytes written to paired node stdin=1920  matches=true
[malformed] rejected: pushAudio base64 must be a valid audio payload  bytes written=0
[base64url] rejected: pushAudio base64 must be a valid audio payload  bytes written=0
```

```text
$ node --import tsx --input-type=module -
{
  "productionPath": [
    "createGoogleMeetChromeNodeInvokePolicy",
    "startNodeRealtimeAudioBridge",
    "startNodeAgentAudioBridge",
    "runtime.nodes.invoke(pullAudio)",
    "provider.sendAudio/transcriptionSession.sendAudio"
  ],
  "policy": {
    "invalidOk": false,
    "invalidMessage": "base64 must be a valid audio payload",
    "invalidDispatches": 0,
    "validOk": true,
    "validDispatches": 1
  },
  "realtime": {
    "pullCount": 3,
    "providerAudioChunks": [
      [
        5,
        4,
        3
      ]
    ],
    "malformedChunkForwarded": false,
    "validChunkForwarded": true,
    "lastInputBytes": 3,
    "consecutiveInputErrors": 0
  },
  "agent": {
    "pullCount": 3,
    "sttAudioChunks": [
      [
        6,
        5,
        4
      ]
    ],
    "malformedChunkForwarded": false,
    "validChunkForwarded": true,
    "lastInputBytes": 3,
    "consecutiveInputErrors": 0
  }
}
```

<details>
<summary>proof-live.ts</summary>

```ts
import { setTimeout as sleep } from "node:timers/promises";
import { resolveGoogleMeetConfig } from "./extensions/google-meet/src/config.ts";
import {
  createGoogleMeetChromeNodeInvokePolicy,
  GOOGLE_MEET_CHROME_NODE_COMMAND,
} from "./extensions/google-meet/src/node-invoke-policy.ts";
import {
  startNodeAgentAudioBridge,
  startNodeRealtimeAudioBridge,
} from "./extensions/google-meet/src/realtime-node.ts";

const invalidPolicyCalls: unknown[] = [];
const validPolicyCalls: unknown[] = [];
const policy = createGoogleMeetChromeNodeInvokePolicy(resolveGoogleMeetConfig({}));
const invalidPolicy = await policy.handle({
  nodeId: "node-1",
  command: GOOGLE_MEET_CHROME_NODE_COMMAND,
  params: { action: "pushAudio", bridgeId: "bridge-1", base64: "not-base64!" },
  config: {} as never,
  pluginConfig: {},
  invokeNode: async (call) => {
    invalidPolicyCalls.push(call);
    return { ok: true, payload: {} };
  },
});
const validPolicy = await policy.handle({
  nodeId: "node-1",
  command: GOOGLE_MEET_CHROME_NODE_COMMAND,
  params: {
    action: "pushAudio",
    bridgeId: "bridge-1",
    base64: Buffer.from([1, 2, 3]).toString("base64"),
  },
  config: {} as never,
  pluginConfig: {},
  invokeNode: async (call) => {
    validPolicyCalls.push(call);
    return { ok: true, payload: { ok: true } };
  },
});

async function runRealtimeBridge() {
  const sentAudio: number[][] = [];
  let pullCount = 0;
  let releaseIdlePull: (() => void) | undefined;
  const runtime = {
    nodes: {
      invoke: async ({ params }: { params?: { action?: string } }) => {
        if (params?.action === "pullAudio") {
          pullCount += 1;
          if (pullCount === 1) {
            return { bridgeId: "bridge-1", base64: "not-base64!" };
          }
          if (pullCount === 2) {
            return { bridgeId: "bridge-1", base64: Buffer.from([5, 4, 3]).toString("base64") };
          }
          await new Promise<void>((resolve) => {
            releaseIdlePull = resolve;
          });
          return { bridgeId: "bridge-1" };
        }
        releaseIdlePull?.();
        releaseIdlePull = undefined;
        return { ok: true };
      },
    },
  };
  const bridge = {
    connect: async () => {},
    sendAudio: (audio: Buffer) => sentAudio.push([...audio]),
    setMediaTimestamp: () => {},
    submitToolResult: () => {},
    acknowledgeMark: () => {},
    close: () => {},
    triggerGreeting: () => {},
    isConnected: () => true,
  };
  const provider = {
    id: "openai",
    label: "OpenAI",
    autoSelectOrder: 1,
    resolveConfig: ({ rawConfig }: { rawConfig: unknown }) => rawConfig,
    isConfigured: () => true,
    createBridge: () => bridge,
  };
  const logger = { info() {}, warn() {}, error() {}, debug() {} };
  const handle = await startNodeRealtimeAudioBridge({
    config: resolveGoogleMeetConfig({ realtime: { provider: "openai", model: "gpt-realtime" } }),
    fullConfig: {} as never,
    runtime: runtime as never,
    meetingSessionId: "meet-1",
    nodeId: "node-1",
    bridgeId: "bridge-1",
    logger,
    providers: [provider as never],
  });
  try {
    for (let i = 0; i < 20 && sentAudio.length === 0; i += 1) {
      await sleep(50);
    }
    const health = handle.getHealth();
    return {
      pullCount,
      providerAudioChunks: sentAudio,
      malformedChunkForwarded: sentAudio.some((chunk) =>
        Buffer.from(chunk).equals(Buffer.from("not-base64!", "base64"))
      ),
      validChunkForwarded: sentAudio.some((chunk) =>
        Buffer.from(chunk).equals(Buffer.from([5, 4, 3]))
      ),
      lastInputBytes: health.lastInputBytes,
      consecutiveInputErrors: health.consecutiveInputErrors,
    };
  } finally {
    await handle.stop();
  }
}

async function runAgentBridge() {
  const sttAudio: number[][] = [];
  let pullCount = 0;
  let releaseIdlePull: (() => void) | undefined;
  const runtime = {
    nodes: {
      invoke: async ({ params }: { params?: { action?: string } }) => {
        if (params?.action === "pullAudio") {
          pullCount += 1;
          if (pullCount === 1) {
            return { bridgeId: "bridge-1", base64: "not-base64!" };
          }
          if (pullCount === 2) {
            return { bridgeId: "bridge-1", base64: Buffer.from([6, 5, 4]).toString("base64") };
          }
          await new Promise<void>((resolve) => {
            releaseIdlePull = resolve;
          });
          return { bridgeId: "bridge-1" };
        }
        releaseIdlePull?.();
        releaseIdlePull = undefined;
        return { ok: true };
      },
    },
  };
  const sttSession = {
    connect: async () => {},
    sendAudio: (audio: Buffer) => sttAudio.push([...audio]),
    close: () => {},
    isConnected: () => true,
  };
  const provider = {
    id: "openai",
    label: "OpenAI",
    defaultModel: "gpt-4o-transcribe",
    autoSelectOrder: 1,
    resolveConfig: ({ rawConfig }: { rawConfig: unknown }) => rawConfig,
    isConfigured: () => true,
    createSession: () => sttSession,
  };
  const logger = { info() {}, warn() {}, error() {}, debug() {} };
  const handle = await startNodeAgentAudioBridge({
    config: resolveGoogleMeetConfig({
      chrome: { audioFormat: "g711-ulaw-8khz" },
      realtime: { provider: "openai", agentId: "jay", introMessage: "" },
    }),
    fullConfig: {} as never,
    runtime: runtime as never,
    meetingSessionId: "meet-1",
    nodeId: "node-1",
    bridgeId: "bridge-1",
    logger,
    providers: [provider as never],
  });
  try {
    for (let i = 0; i < 20 && sttAudio.length === 0; i += 1) {
      await sleep(50);
    }
    const health = handle.getHealth();
    return {
      pullCount,
      sttAudioChunks: sttAudio,
      malformedChunkForwarded: sttAudio.some((chunk) =>
        Buffer.from(chunk).equals(Buffer.from("not-base64!", "base64"))
      ),
      validChunkForwarded: sttAudio.some((chunk) =>
        Buffer.from(chunk).equals(Buffer.from([6, 5, 4]))
      ),
      lastInputBytes: health.lastInputBytes,
      consecutiveInputErrors: health.consecutiveInputErrors,
    };
  } finally {
    await handle.stop();
  }
}

console.log(JSON.stringify({
  productionPath: [
    "createGoogleMeetChromeNodeInvokePolicy",
    "startNodeRealtimeAudioBridge",
    "startNodeAgentAudioBridge",
    "runtime.nodes.invoke(pullAudio)",
    "provider.sendAudio/transcriptionSession.sendAudio",
  ],
  policy: {
    invalidOk: invalidPolicy.ok,
    invalidMessage: invalidPolicy.message,
    invalidDispatches: invalidPolicyCalls.length,
    validOk: validPolicy.ok,
    validDispatches: validPolicyCalls.length,
  },
  realtime: await runRealtimeBridge(),
  agent: await runAgentBridge(),
}, null, 2));
```

</details>

